    NOW(), NOW(), #{updemp, jdbcType=VARCHAR}
)

INSERT INTO campaign_call_list (
    cmpycd, camp_no, surv_gb, cust_nm, email, tel_no, status, rslt_cd, userid, ext_data, addtime, updtime, updemp
) VALUES (
    #{cmpycd, jdbcType=VARCHAR}, #{camp_no, jdbcType=VARCHAR}, #{surv_gb, jdbcType=VARCHAR},
    #{cust_nm, jdbcType=VARCHAR}, #{email, jdbcType=VARCHAR}, #{tel_no, jdbcType=VARCHAR},
    #{status, jdbcType=VARCHAR}, #{rslt_cd, jdbcType=VARCHAR}, #{userid, jdbcType=VARCHAR},
    #{ext_data, jdbcType=VARCHAR, typeHandler=com.crmbank.erp.global.handler.JsonTypeHandler},
    NOW(), NOW(), #{updemp, jdbcType=VARCHAR}
)

