mapper.select:
SELECT rs.rslt_no AS id, rs.rslt_no AS rslt_no, rs.call_seq AS callSeq, rs.cmpycd AS cmpycd, rs.camp_no AS campNo, c.camp_nm AS campNm, rs.userid AS userId, u.usernm AS userNm, cl.cust_nm AS custNm, cl.tel_no AS telNo, rs.rslt_cd AS rsltCd, bc.codenm AS rsltCdNm, IFNULL(rs.grade, 'A') AS grade, IFNULL(rs.evaluator, #{userid}) AS evaluator, DATE_FORMAT(rs.start_dtime, '%Y-%m-%d %H:%i:%s') AS callDtime, rs.rec_file AS recUrl, rs.remark AS managerComment, CONCAT('[상담 메모]\n', IFNULL(rs.remark, ''), '\n[채팅로그]\n', IFNULL(rs.chat_log, '')) AS callMemo FROM campaign_rslt_mst rs LEFT JOIN campaign_mst c ON rs.cmpycd = c.cmpycd AND rs.camp_no = c.camp_no LEFT JOIN campaign_call_list cl ON rs.cmpycd = cl.cmpycd AND rs.call_seq = cl.call_seq LEFT JOIN haba900t_tbl bc ON bc.cdtype = '920' AND rs.rslt_cd = bc.codecd LEFT JOIN haba920t_tbl u ON rs.cmpycd = u.cmpycd AND rs.userid = u.userid WHERE rs.cmpycd = #{cmpycd}
AND rs.camp_no = #{campno}
AND rs.userid = #{userid}
AND DATE(rs.start_dtime) BETWEEN #{frdt} AND #{todt}
AND (cl.cust_nm LIKE CONCAT('%', #{keyword}, '%') OR cl.tel_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY rs.rslt_no DESC

SELECT cl.userid AS userid, u.usernm AS userNm, cl.camp_no AS campNo, c.camp_nm AS campNm, COUNT(cl.call_seq) AS totCnt, SUM(CASE WHEN cl.rslt_cd = '041' THEN 1 ELSE 0 END) AS absentCnt, SUM(CASE WHEN cl.rslt_cd = '042' THEN 1 ELSE 0 END) AS threeWayCnt, SUM(CASE WHEN cl.rslt_cd = '043' THEN 1 ELSE 0 END) AS surveyStopCnt, SUM(CASE WHEN cl.rslt_cd = '061' THEN 1 ELSE 0 END) AS rejectCnt, SUM(CASE WHEN cl.rslt_cd = '062' THEN 1 ELSE 0 END) AS wrongNumCnt, SUM(CASE WHEN cl.rslt_cd = '063' THEN 1 ELSE 0 END) AS etcCnt, SUM(CASE WHEN cl.rslt_cd = '081' THEN 1 ELSE 0 END) AS reserveCnt, SUM(CASE WHEN cl.rslt_cd = '099' THEN 1 ELSE 0 END) AS successCnt FROM campaign_call_list cl LEFT JOIN campaign_mst c ON cl.cmpycd = c.cmpycd AND cl.camp_no = c.camp_no LEFT JOIN haba920t_tbl u ON cl.cmpycd = u.cmpycd AND cl.userid = u.userid WHERE cl.cmpycd = #{cmpycd}
AND cl.camp_no = #{campno}
AND cl.userid = #{userid}
AND DATE(cl.addtime) BETWEEN #{frdt} AND #{todt}
GROUP BY cl.camp_no, c.camp_nm, cl.userid, u.usernm ORDER BY c.camp_nm ASC, u.usernm ASC

SELECT cl.call_seq AS callSeq, cl.call_seq AS id, cl.cust_nm AS custNm, cl.tel_no AS telNo, cl.rslt_cd AS rsltCd, IFNULL(bc.codenm, cl.rslt_cd) AS rsltCdNm, DATE_FORMAT(rs.start_dtime, '%Y-%m-%d %H:%i:%s') AS callDtime, IF(rs.rec_file IS NOT NULL AND rs.rec_file != '', '유', '무') AS recYn, rs.rec_file AS recUrl FROM campaign_call_list cl LEFT JOIN campaign_rslt_mst rs ON cl.cmpycd = rs.cmpycd AND cl.call_seq = rs.call_seq LEFT JOIN haba900t_tbl bc ON bc.cdtype = '920' AND cl.rslt_cd = bc.codecd WHERE cl.cmpycd = #{cmpycd}
AND cl.camp_no = #{campno}
AND cl.userid = #{userid}
AND (cl.rslt_cd = #{status} OR bc.codenm LIKE CONCAT('%', #{status}, '%'))
ORDER BY cl.call_seq DESC
